PRAGMA foreign_keys = ON;

-- Fotos reais pesquisadas e vinculadas individualmente ao código material.
ALTER TABLE products ADD COLUMN imagem_url TEXT;

CREATE TABLE _migration_0027_product_images (
  material_code TEXT PRIMARY KEY COLLATE NOCASE,
  imagem_url TEXT NOT NULL CHECK (trim(imagem_url) <> '')
);


CREATE TABLE _migration_0027_guard (
  valid INTEGER NOT NULL CHECK (valid = 1)
);

SELECT CASE
  WHEN (SELECT COUNT(*) FROM _migration_0027_product_images) = 291
   AND (SELECT COUNT(*) FROM _migration_0027_product_images WHERE imagem_url LIKE 'https://%') = 291
  THEN 1 ELSE 0 END;

UPDATE products
SET imagem_url = (
      SELECT source.imagem_url
      FROM product_variants variant
      JOIN _migration_0027_product_images source
        ON source.material_code = variant.sku COLLATE NOCASE
      WHERE variant.product_id = products.id
      LIMIT 1
    ),
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
WHERE EXISTS (
  SELECT 1
  FROM product_variants variant
  JOIN _migration_0027_product_images source
    ON source.material_code = variant.sku COLLATE NOCASE
  WHERE variant.product_id = products.id
);

DROP TABLE _migration_0027_guard;
DROP TABLE _migration_0027_product_images;

